function F({registerIndicator:x,sourceValues:R,nulls:S}){const v=(b,m)=>{const k=b.length,y=new Array(k).fill(NaN),p=1/m,l=1-p;let o=NaN,n=0,c=0,a=1,r=!0;for(let d=0;d<k;d++){let u=50;const s=b[d];if(Number.isFinite(s))if(!Number.isFinite(o))o=s;else{const f=s-o,e=f>0?f:0,t=f<0?-f:0;if(o=s,n=p*e+l*n,c=p*t+l*c,r){a*=l;const i=a>1e-10?1/(1-a):1,N=n*i,P=c*i,h=N+P;u=h!==0?100*N/h:50,a<=1e-10&&(r=!1)}else{const i=n+c;u=i!==0?100*n/i:50}}y[d]=u}return y};x({id:"oa-crsi",name:"Connors RSI (CRSI)",category:"Oscillators",placement:"pane",inputs:[{key:"source",type:"source",label:"Source",default:"close"},{key:"rsiPeriod",type:"number",label:"RSI Period",default:3,min:1,max:500,step:1},{key:"streakPeriod",type:"number",label:"Streak RSI Period",default:2,min:1,max:500,step:1},{key:"rankPeriod",type:"number",label:"Percent Rank Period",default:100,min:1,max:1e3,step:1}],plots:[{key:"crsi",type:"line",title:"CRSI",style:{color:"#ffeb3b",lineWidth:2}}],levels:()=>[{price:70,title:"Overbought",color:"#787b86",dashed:!0},{price:30,title:"Oversold",color:"#787b86",dashed:!0}],calc(b,m){const k=Math.max(1,Math.min(500,Math.floor(Number(m.rsiPeriod)||3))),y=Math.max(1,Math.min(500,Math.floor(Number(m.streakPeriod)||2))),p=Math.max(1,Math.min(1e3,Math.floor(Number(m.rankPeriod)||100))),l=R(b,m.source??"close"),o=b.length,n=v(l,k),c=new Array(o).fill(0);let a=NaN,r=0;for(let e=0;e<o;e++){const t=l[e];Number.isFinite(t)&&(Number.isFinite(a)?t>a?r=r>=0?r+1:1:t<a?r=r<=0?r-1:-1:r=0:r=0,a=t),c[e]=r}const d=v(c,y),u=new Array(o).fill(0);let s=NaN;for(let e=0;e<o;e++){const t=l[e];let i=0;Number.isFinite(t)&&Number.isFinite(s)&&s!==0&&(i=(t-s)/s*100),Number.isFinite(t)&&(s=t),u[e]=i}const f=new Array(o).fill(NaN);for(let e=0;e<o;e++){const t=Math.max(0,e-p),i=e-t;let N=0;for(let M=t;M<e;M++)u[M]<u[e]&&(N+=1);const P=i>0?N/i*100:50,h=(n[e]+d[e]+P)/3;Number.isFinite(h)&&(f[e]=Math.max(0,Math.min(100,h)))}return{crsi:S(f)}}})}export{F as default};
